Here's an example of an LDPC (Low-Density Parity Check) encoder in SystemVerilog for an FPGA implementation:

```verilog
module ldpc_encoder(
    input wire clk,
    input wire reset,
    input wire data_in,
    output wire data_out,
    output wire parity_out
);

// Define the LDPC code parameters
const int DATA_WIDTH = 8;
const int PARITY_WIDTH = 4;
const int LDPC_MATRIX_SIZE = 8;

// Define the LDPC matrix
logic [LDPC_MATRIX_SIZE - 1:0] ldpc_matrix[DATA_WIDTH - 1:0];

// Initialize the LDPC matrix
initial begin
    ldpc_matrix[7] = 3'b111;
    ldpc_matrix[6] = 3'b110;
    ldpc_matrix[5] = 3'b101;
    ldpc_matrix[4] = 3'b100;
    ldpc_matrix[3] = 3'b011;
    ldpc_matrix[2] = 3'b010;
    ldpc_matrix[1] = 3'b001;
    ldpc_matrix[0] = 3'b000;
end

// Encode the data input
always @(posedge clk or posedge reset) begin
    if (reset) begin
        data_out <= 8'b00000000;
        parity_out <= 4'b0000;
    end else begin
        logic [DATA_WIDTH - 1:0] data = data_in;
        logic [PARITY_WIDTH - 1:0] parity = 0;

        for (int i = 0; i < DATA_WIDTH; i++) begin
            parity += ldpc_matrix[i][data[i]];
        end

        data_out <= data;
        parity_out <= parity;
    end

