```cpp
#include <iostream>
#include <string>
#include <vector>
#include <stdexcept>

using namespace std;

// Recursive function to generate the Fibonacci sequence
vector<int> fibonacci(int n, int a, int b) {
    if (n == 0) {
        return vector<int>();
    } else {
        vector<int> result = fibonacci(n - 1, b, a + b);
        result.push_back(a);
        return result;
    }
}

int main() {
    int first_element, second_element, num_elements;
    cout << "Enter the first two elements of the Fibonacci sequence: ";
    cin >> first_element >> second_element;

    // Error handling for invalid inputs
