Here's a MATLAB function that converts a given phrase to its Morse Code representation using the International Morse Code standard:

```matlab
function morse_code = convert_to_morse(phrase)
    % Convert input phrase to uppercase
    phrase = upper(phrase);

    % Initialize empty string to store Morse Code representation
    morse_code = '';

    % Loop through each character in the input phrase
    for i = 1:length(phrase)
        % Get the Morse Code representation of the current character
        morse_code = [morse_code, moc(phrase(i))];
    end
end

function morse_code = moc(char)
    % Check if the character is a letter or a digit
    if isletter(char)
        % Get the Morse Code representation of the letter
        morse_code = char_moc(char);
    else
        % Get the Morse Code representation of the digit
        morse_code = digit_moc(char);
    end
end

function morse_code = char_moc(char)
    % Get the Morse Code representation of the letter from the table
    morse_code = table_lookup(char, 'Morse Code');
end

function morse_code = digit_moc(digit)
    % Get the Morse Code representation of the digit from the table
    morse_code = table_lookup(digit, 'Morse Code');
end

% Table lookup function
function morse_code = table_lookup(input, table)
    % Search for the input value in the table
    index = search(table(1), input);

    % Return the corresponding Morse Code representation
    morse_code = table(2)(index);
end
```

To use this function, simply call it with your input phrase as an argument:

