const { NestFactory } = require('@nestjs/core');
const { TypeOrmModule } = require('@nestjs/typeorm');
const { User, Permission } = require('./models');
const { AccessPermissionGuard } = require('./guards/access-permission.guard');

async function bootstrap() {
  const app = await NestFactory.create(TypeOrmModule.forRoot({
    type: 'mysql',
    host: 'localhost',
    port: 3306,
    username: 'root',
    password: 'password',
    database: 'mydatabase',
    entities: [User, Permission],
    synchronize: true,
  }));

  app.useGlobalGuards(new AccessPermissionGuard());

  app.get('/permissions', async () => {
    const permissions = await app.get(Permission).find();
    return permissions.map((p) => p.name);
  });

  await app.listen(3000);
}

bootstrap();
```

