<?php

use Illuminate\Database\Migrations\Migration;
use Illuminate\Database\Schema\Blueprint;
use Illuminate\Support\Facades\Schema;

class CreateUsersTable extends Migration
{
    /**
     * Run the migrations.
     *
     * @return void
     */
    public function up()
    {
        Schema::create('users', function (Blueprint $table) {
            $table->id();
            $table->string('name');
            $table->string('email')->unique();
            $table->string('password');
            $table->timestamps();

            // Relationships
            $table->hasMany('cars');
            $table->hasMany('pets');
            $table->hasOne('house');
        });
    }

    /**
     * Reverse the migrations.
     *
     * @return void
     */
    public function down()
    {
        Schema::dropIfExists('users');
    }
}
```

This migration creates a "users" table with the following columns:

* id (integer, primary key)
* name (string)
* email (string, unique)
* password (string)
* created_at (timestamp)
* updated_at (timestamp)

It also defines relationships between the "users" table and the "cars", "pets", and "houses" tables using the `hasMany`, `hasOne`, and `belongsTo` methods. The `hasMany` method creates a one-to-many relationship between the "users" table and the "cars" and "pets" tables, while the `hasOne` method creates a one-to-one relationship between the "users" table and the "house" table.

