```javascript
export const useTemperatureConverter = () => {
  const [temperatureValue, setTemperatureValue] = useState(null);
  const [selectedUnit, setSelectedUnit] = useState('C'); // Default unit is Celsius

  const handleInputChange = (event) => {
    setTemperatureValue(parseFloat(event.target.value));
  };

  const handleUnitChange = (event) => {
    setSelectedUnit(event.target.value);
  };

  const convertTemperature = () => {
    if (temperatureValue === null || selectedUnit === '') {
      return;
    }

    let convertedValue = 0;

    if (selectedUnit === 'C') {
      convertedValue = (temperatureValue * 1.8) + 32;
    } else if (selectedUnit === 'F') {
      convertedValue = (temperatureValue - 32) / 1.8;
    }

    return convertedValue.toFixed(2);
  };

  return { temperatureValue, selectedUnit, handleInputChange, handleUnitChange, convertTemperature };
};
```

