To prevent the planets from being too close together, you can implement a simple collision detection system and adjust the planet's positions accordingly. Here's an updated version of your `generateRandomPlanets` function:

```javascript
const generateRandomPlanets = (numPlanets, minDistance) => {
  const planets = [];
  let attempts = 0;

  while (planets.length < numPlanets && attempts < 100) {
    attempts++;

    const planet = {
      position: [
        randomPosition(-30, 30),
        randomPosition(-30, 30),
        randomPosition(-30, 30),
      ],
      size: randomSize(1, 5) * scale,
      color: randomColor(),
      ringSize: 0.2 * scale,
      ringColor: randomColor(),
      ringNoise: 0.3 * scale,
    };

    // Check if planet is too close to any existing planet
    const tooClose = planets.some((p) =>
      p.position.some((coord, index) => {
        return Math.abs(coord - planet.position[index]) < minDistance;
      })
    );

    if (!tooClose) {
      planets.push(planet);
    }
  }

  // Adjust planet positions to avoid collisions
  for (let i = 0; i < planets.length; i++) {
    for (let j = i + 1; j < planets.length; j++) {
      const distance = planets[i].position.map((a, index) => {
        return Math.abs(a - planets[j].position[index]);
      });

      if (distance.reduce((a, b) => a + b) < minDistance) {
        planets[i].position = [
          planets[i].position[0],
          planets[i].position[1],
          planets[i].position[2],
        ];

        j--;
      }
    }
  }

  return planets;
};
```

