Here's the `redis.js` file inside the `utils` folder with the required class and instance:

```javascript
const { Redis } = require('ioredis');

class RedisClient {
  constructor() {
    this.client = new Redis({
      host: 'localhost',
      port: 6379,
      password: 'your_password_if_required',
    });

    this.client.on('error', (err) => {
      console.error('Redis error:', err);
    });
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (err) {
      console.error('Redis is not alive:', err);
      return false;
    }
  }

  async get(key) {
    try {
      const value = await this.client.get(key);
      return value;
    } catch (err) {
      console.error(`Error getting from Redis: ${key}`, err);
      return null;
    }
  }

  async set(key, value, duration) {
    try {
      await this.client.setex(key, duration, value);
      return true;
    } catch (err) {
      console.error(`Error setting in Redis: ${key}`, err);
      return false;
    }
  }

  async del(key) {
    try {
      await this.client.del(key);
      return true;
    } catch (err) {
      console.error(`Error deleting from Redis: ${key}`, err);
      return false;
    }
  }
}

const redisClient = new RedisClient();

module.exports = redisClient;
```

Make sure to replace `'your_password_if_required'` with your actual Redis password if you have one.

