To find the kth largest element in a list, we can use the quickselect algorithm. This algorithm has a time complexity of O(n), which is efficient for large lists. Here's how we can implement it in Python:

```python
def quickselect(numbers, k):
    def partition(left, right):
        pivot = numbers[right]
        i = left - 1
        for j in range(left, right):
            if numbers[j] <= pivot:
                i += 1
                numbers[i], numbers[j] = numbers[j], numbers[i]
        numbers[i + 1], numbers[right] = numbers[right], numbers[i + 1]
        return i + 1

    def select(left, right, k):
        if left == right:
            return numbers[left]
        pivot_index = partition(left, right)
        if pivot_index == k - 1:
            return numbers[pivot_index]
        elif pivot_index > k - 1:
            return select(left, pivot_index - 1, k)
        else:
            return select(pivot_index + 1, right, k)

    return select(0, len(numbers) - 1, k)

